/**
 * One-time upgrade of point IDs saved before stable IDs (Nov 2026): starred stops in
 * localStorage and `?point=` share links. Legacy IDs were row numbers / ranks that the
 * open-data portals reassign on each import, so after a refresh they would silently
 * point at a different stop.
 *
 * Costs nothing for visitors without legacy IDs; otherwise fetches only the affected
 * cities' maps (generated by scripts/generate-id-migrations.ts), once.
 */
import { legacyIdCity, type LegacyIdCity } from '../cities/pointId';

const STARRED_KEY = 'starredPoints';

/** Key into the city's migration map: the legacy ID minus its city prefix and any parts that don't identify the stop. */
function legacyKey(city: LegacyIdCity, id: string): string {
  const key = id.slice(city.length + 1);
  if (city === 'taichung') return key.replace(/-d[1-7]-(garbage|recycling)$/, '');
  // Kaohsiung had one stop per coordinate; the plate suffix is irrelevant
  if (city === 'kaohsiung') return key.slice(0, key.indexOf('-'));
  return key;
}

async function loadMap(city: LegacyIdCity): Promise<Record<string, string> | null> {
  try {
    const res = await fetch(`/migrations/point-ids-v1-${city}.json`);
    return res.ok ? await res.json() : null;
  } catch {
    return null;
  }
}

/**
 * Resolve legacy IDs. `resolved` holds the ones found; `obsolete` the ones whose map loaded
 * but doesn't know them (the stop no longer existed). IDs whose map failed to load are in neither.
 */
async function resolve(ids: string[]): Promise<{ resolved: Map<string, string>; obsolete: Set<string> }> {
  const cities = new Set(ids.map(legacyIdCity).filter((c): c is LegacyIdCity => c !== null));
  const maps = new Map<LegacyIdCity, Record<string, string> | null>();
  await Promise.all([...cities].map(async city => maps.set(city, await loadMap(city))));

  const resolved = new Map<string, string>();
  const obsolete = new Set<string>();
  for (const id of ids) {
    const city = legacyIdCity(id);
    const map = city && maps.get(city);
    if (!city || !map) continue;
    const suffix = map[legacyKey(city, id)];
    if (suffix) resolved.set(id, `${city}-${suffix}`);
    else obsolete.add(id);
  }
  return { resolved, obsolete };
}

function readStarred(): string[] {
  try {
    const parsed = JSON.parse(localStorage.getItem(STARRED_KEY) ?? '[]');
    return Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string') : [];
  } catch {
    return [];
  }
}

export async function migrateLegacyPointIds(): Promise<void> {
  const starred = readStarred();
  const url = new URL(window.location.href);
  const sharedId = url.searchParams.get('point');

  const legacy = [...starred, ...(sharedId ? [sharedId] : [])].filter(id => legacyIdCity(id) !== null);
  if (legacy.length === 0) return;

  const { resolved, obsolete } = await resolve(legacy);

  if (starred.some(id => legacyIdCity(id))) {
    // Obsolete stars point at stops that no longer exist; dropping them stops a refetch on every visit.
    // A map that failed to load leaves its IDs untouched so the next visit retries.
    const upgraded = starred.filter(id => !obsolete.has(id)).map(id => resolved.get(id) ?? id);
    try {
      localStorage.setItem(STARRED_KEY, JSON.stringify([...new Set(upgraded)]));
    } catch {
      // Storage unavailable (private mode): the stars just stay unmigrated
    }
    const unresolved = starred.filter(id => legacyIdCity(id) && !resolved.has(id) && !obsolete.has(id));
    if (unresolved.length > 0) console.warn('Could not migrate starred stops (will retry):', unresolved);
  }

  if (sharedId && resolved.has(sharedId)) {
    url.searchParams.set('point', resolved.get(sharedId)!);
    window.history.replaceState(window.history.state, '', url);
  }
}
